import{_ as p,a0 as R,w as n,s as l,ao as d,I as r,a1 as a,A as o,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Red Hat 为64位ARM服务器做准备 | LCTT x X-CMD","titleTemplate":false,"description":"Red Hat 为64位ARM服务器做准备 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Red Hat 为64位ARM服务器做准备 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Red Hat 为64位ARM服务器做准备 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Red Hat prepares for 64-bit ARM servers","title":"Red Hat 为64位ARM服务器做准备","tag":"201311","desc":""},"relativePath":"201311/Red Hat prepares for 64-bit ARM servers.md","filePath":"[post].md"}'),M={name:"201311/Red Hat prepares for 64-bit ARM servers.md"};function i(A,t,u,m,f,T){const s=R("Link");return n(),l("div",null,[t[13]||(t[13]=d('<h1 id="red-hat-为64位arm服务器做准备" tabindex="-1">Red Hat 为64位ARM服务器做准备 <a class="header-anchor" href="#red-hat-为64位arm服务器做准备" aria-label="Permalink to “Red Hat 为64位ARM服务器做准备”">​</a></h1><blockquote><p>ARM处理器可能带来具有成千上万的节点的堆叠服务器，Red Hat的ARM首席架构师预测说</p></blockquote><p>来自IDG新闻服务：企业开源软件供应商Red Hat公司正在密切关注服务器的64位ARM处理器的发展，以建立在数据中心的新生平台上的专业能力。</p><p>“你们在当今的商业产品市场看不到我们，但我们已经建立了超越如今一些64位技术的能力。所以接下来，如果我们有一个需要应对的市场，我们将有能力应对，”Red Hat首席ARM设计师Jon Masters说。这是Masters周五在华盛顿特区举行的USENIX LISA（大型安装系统管理）会议上提出的。</p><p>ARM处理器代表了“计算上翻天覆地的变化，”Masters说。虽然已经在智能手机和嵌入式计算设备占据主导地位，ARM处理器架构还可以在数据中心发挥作用。在过去的一年中，基于ARM处理器的服务器已经开始出现在服务器市场。惠普已经开始销售基于ARM架构的Moonshot系列服务器。</p><p>对于数据中心，ARM可能会因其低功耗设计而带来超大规模计算时代，这样数千个微型计算节点可以打包成一个堆叠服务器。“我们在不久的将来能够建立起完全区别于现今的规模。”Masters说。</p><p>ARM处理器可能无法以x86处理器的速度运行，但它们可以提供大部分的性能而只消耗一小部分能源，这意味着在一个较小的空间可以打包更多的处理器。“你可以用你手机中相同的技术，作为高密度服务器设计的一部分”，Masters说。</p><p>他说，许多工作并不需要最快的处理器。相反，工作负载可以分布在更多的处理器上。“这和我能移动多少数据有关系，并不一定和我能做多少计算有关，”他说。例如，云计算和Web应用程序运行在多个服务器上，和运行在数量较少但速度更快的服务器上的表现会同样出色。</p><p>ARM的设计也可以简化数据中心操作。ARM的芯片内系统的设计方式可以解决管理许多服务器的外部元件的需要。例如，ARM处理器可以提供交叉互联，减少外部电缆和顶级机架交换机的需要。</p><p>“每一个刀片都具有离散布线已经指日可待了， ”他说。</p><p>Masters说超大规模计算还需要做大量的工作。</p><p>ARM授权它的架构而不是和英特尔一样卖处理器。其结果是，从不同供应商提供的不同的ARM处理器有相当程度的变化。“有很多我们不需要的，不必要的变化，”Masters说。 ”这可能成为需要统一系统来管理集体的数据中心的一个问题。</p>',12)),r("p",null,[a(s,{href:"http://www.linaro.org/"},{default:o(()=>[...t[0]||(t[0]=[e("Linaro",-1)])]),_:1}),t[1]||(t[1]=e("是一个致力于为ARM平台和部分已经标准化ARM任务开发核心开源软件的产业群。Red Hat的工程师发挥了重要作用，Linaro企业集团，或称为LEG，一直在努力规范软件，让用户可以得到一个能运行在不同供应商提供的ARM处理器的Linux版本。”这些都是在企业领域的基本期望，”Masters说。",-1))]),t[14]||(t[14]=r("p",null,"“我们需要把重心放在如何使它们从根本上兼容，这样你可以进一步增加堆叠，”他说。",-1)),t[15]||(t[15]=r("p",null,"另一个问题是对外围设备的支持，仍然没有标准化的32位ARM处理器。Masters说，LEG正在考虑使用64位ARM处理器的ACPI（高级配置和电源接口）标准或UEFI（统一可扩展固件接口）。随着时间的推移，ARM将提供一个类似自动化总线的能力，比如将提供支持x86的机器的PCI总线。",-1)),t[16]||(t[16]=r("p",null,"Masters说，Red Hat还没有宣布任何关于什么时候会发布一个ARM架构的Red Hat企业Linux版本的通知，但他明确指出，测试了许多RHEL应用程序的社区Linux发行版Fedora项目，现在已经为ARM提供了一个发行版。",-1)),t[17]||(t[17]=r("hr",null,null,-1)),r("p",null,[t[3]||(t[3]=e("via: ",-1)),a(s,{href:"http://www.computerworld.com/s/article/9243921/Red_Hat_prepares_for_64_bit_ARM_servers?taxonomyId=122"},{default:o(()=>[...t[2]||(t[2]=[e("http://www.computerworld.com/s/article/9243921/Red_Hat_prepares_for_64_bit_ARM_servers?taxonomyId=122",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=e("译者：",-1)),a(s,{href:"https://github.com/whatever1992"},{default:o(()=>[...t[4]||(t[4]=[e("whatever1992",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),a(s,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const C=p(M,[["render",i]]);export{L as __pageData,C as default};
